insert into public.storage_location_detail_mappings
    (item_source_code, normalized_raw_storage_name, detail_org_id, storage_location_id, evidence_note)
select r.item_source_code, r.normalized_raw_storage_name, r.detail_org_id, l.id, r.evidence_note
from rules r
join public.storage_locations l on l.location_source_code = r.location_source_code
    and l.source_key = r.source_key and l.is_active
on conflict (item_source_code, normalized_raw_storage_name, detail_org_id) do nothing;
